#!/usr/bin/env python3
"""Colour of noise: white, pink and red noise, generated by spectral shaping and
measured for spectral slope, octave-band energy and the scaling of the mean.

Run with the project venv:

    /Users/miroslav/Documents/workspace/geophysics/.venv/bin/python noise_colour_demo.py

Everything here is SYNTHETIC.  The coloured series are filters applied to
generated white noise; no data are read and no published number is used.

Sections
--------
1. Construction: a power law f^-alpha imposed on white noise.
2. Measured spectral slope versus the imposed exponent alpha.
3. Octave-band energy ratios versus 2^(1-alpha).
4. Variance of the time average versus record length, for each colour.
5. Why the colour matters: the standard error of a mean from a 1/f record.
"""

import numpy as np
from scipy import signal

RNG = np.random.default_rng(20261014)

FS = 100.0          # sampling rate, Hz
DT = 1.0 / FS
N = 1 << 16         # 65536 samples for the spectra
L = 1 << 17         # 131072 samples for the long-record studies
M = 200             # ensemble size


def section(title):
    print(f"\n{'=' * 68}\n{title}\n{'=' * 68}")


def coloured_noise(n, alpha, rng, dt=DT):
    """Real noise whose one-sided PSD is proportional to f^-alpha (alpha >= 0).

    A white sequence is filtered in the frequency domain by f^(-alpha/2); the
    zero-frequency bin is set to zero so that the series has no trend term.
    """
    x = rng.standard_normal(n)
    f = np.fft.rfftfreq(n, dt)
    shape = np.ones_like(f)
    shape[1:] = (f[1:] / f[1]) ** (-alpha / 2.0)
    shape[0] = 0.0
    return np.fft.irfft(np.fft.rfft(x) * shape, n)


def spectral_slope(y, f_lo=0.5, f_hi=40.0):
    """Least-squares slope of log10(PSD) versus log10(f) over a band."""
    f, p = signal.welch(y, fs=FS, nperseg=4096, window="hann", detrend=False,
                        scaling="density")
    band = (f >= f_lo) & (f <= f_hi) & (p > 0)
    slope = np.polyfit(np.log10(f[band]), np.log10(p[band]), 1)[0]
    return slope, f, p


def octave_ratios(y):
    """Power in successive octave bands [1,2),[2,4),... and their ratios."""
    f, p = signal.welch(y, fs=FS, nperseg=4096, window="hann", detrend=False,
                        scaling="density")
    df = f[1] - f[0]
    edges = [(1, 2), (2, 4), (4, 8), (8, 16), (16, 32)]
    band_power = []
    for lo, hi in edges:
        sel = (f >= lo) & (f < hi)
        band_power.append(np.sum(p[sel]) * df)
    band_power = np.array(band_power)
    return edges, band_power, band_power[1:] / band_power[:-1]


def main():
    colours = [("white", 0.0), ("pink", 1.0), ("red", 2.0)]

    section("1. Construction of coloured noise by spectral shaping")
    print(f"  record {N} samples at {FS:.1f} Hz ({N * DT:.1f} s), "
          f"shape(f) = (f/f1)^(-alpha/2)")
    print("  one-sided PSD of the result is proportional to f^(-alpha).")
    for name, alpha in colours:
        print(f"    {name:5s}: alpha = {alpha:.1f}")

    section("2. Measured spectral slope versus the imposed exponent")
    print("  Welch PSD, nperseg=4096, slope fitted over 0.5-40 Hz")
    print("     colour   alpha   measured slope (log10 PSD vs log10 f)")
    slopes = {}
    spectra = {}
    for name, alpha in colours:
        y = coloured_noise(N, alpha, RNG)
        slope, f, p = spectral_slope(y)
        slopes[name] = slope
        spectra[name] = (f, p)
        print(f"     {name:8s} {alpha:5.1f}   {slope:8.3f}")
    print("  -> the measured slope reproduces -alpha; the residual is estimator")
    print("     scatter on a single realisation.")

    section("3. Octave-band energy versus the 2^(1-alpha) prediction")
    print("     colour   band powers over [1,2),[2,4),[4,8),[8,16),[16,32) Hz")
    for name, alpha in colours:
        edges, bp, ratios = octave_ratios(coloured_noise(N, alpha, RNG))
        pred = 2.0 ** (1.0 - alpha)
        print(f"     {name:6s}   " + " ".join(f"{v:.4g}" for v in bp))
        print(f"              successive ratios = "
              f"{' '.join(f'{r:.3f}' for r in ratios)}   "
              f"(predicted {pred:.3f})")
    print("  -> white noise doubles its energy per octave, red noise halves it,")
    print("     and pink noise holds it roughly constant: equal energy per")
    print("     octave IS the defining property of f^-1.")

    section("4. Structure function: how excursions grow with the timescale")
    print("  D(T) = E[(y(t+T) - y(t))^2] on records of 16384 samples, "
          "100 realisations")
    print("  D is a variance, so it carries the units of the series squared.")
    print("     colour   T=4      T=16     T=64     T=256    T=1024   slope")
    lags = (4, 16, 64, 256, 1024)
    for name, alpha in colours:
        d = np.empty((100, len(lags)))
        for m in range(100):
            y = coloured_noise(1 << 14, alpha, RNG)
            for j, t in enumerate(lags):
                d[m, j] = np.mean((y[t:] - y[:-t]) ** 2)
        dm = d.mean(axis=0)
        ds = d.std(axis=0)
        slope = np.polyfit(np.log10(lags), np.log10(dm), 1)[0]
        print(f"     {name:6s}   " + "  ".join(f"{v:.3g}" for v in dm)
              + f"   {slope:+.3f}")
        print(f"               scatter (1 s.d.): "
              + "  ".join(f"{v:.2g}" for v in ds))
    print("  -> white noise has a structure function independent of T: its")
    print("     excursions do not grow with the timescale, so an average keeps")
    print("     helping.  Red noise has D growing about linearly in T: the series")
    print("     wanders, and a longer record contains larger excursions, not just")
    print("     more of the same.  Pink noise grows only slowly (roughly")
    print("     logarithmically), the hallmark of long memory.")

    section("5. Consequence: the standard error of a mean")
    print("  same nominal number of samples (4096) from each colour")
    for name, alpha in colours:
        y = coloured_noise(N, alpha, RNG)
        seg = y[:4096]
        naive = seg.std(ddof=1) / np.sqrt(4096)
        # effective sample count from the integrated autocorrelation time
        xc = np.correlate(seg - seg.mean(), seg - seg.mean(), "full")[4095:]
        acf = xc / xc[0]
        cut = np.argmax(acf < 0.05) if np.any(acf < 0.05) else acf.size
        tau_int = 1 + 2 * np.sum(acf[1:max(cut, 2)])
        se_eff = seg.std(ddof=1) / np.sqrt(4096 / tau_int)
        print(f"     {name:6s}: naive sigma/sqrt(n) = {naive:.4f}, "
              f"tau_int = {tau_int:.1f} samples, "
              f"corrected = {se_eff:.4f}, ratio = {se_eff / naive:.2f}x")
    print("  -> the naive standard error assumes white noise.  For coloured")
    print("     noise it can be wrong by a large factor, and the correction is")
    print("     the same effective-sample-count idea as in lesson 05-01.")


if __name__ == "__main__":
    main()
